  'bd.title': 'Tabuleiro', 'bd.quilt': 'Colcha havaiana', 'bd.ocean': 'Arte oceânica', 'bd.kona': 'Arte de Kona', 'bd.stone': 'Papamū de pedra', 'bd.koa': 'Tabuleiro de koa', 'bd.mono': 'Cinza moderno', 'bd.sunset': 'Pôr do sol', 'bd.midnight': 'Meia-noite', 'pcs.title': 'Pedras', 'pcs.stone': 'Seixos de basalto e coral', 'pcs.pearl': 'Pérolas', 'pcs.koa': 'Madeira de koa', 'pcs.glass': 'Vidro', 'pcs.matte': 'Fosco', 'res.why.stuck': 'O rival não pôde saltar (vence quem salta por último)',
  'rv.note': 'Ruim = um lance que vira vitória em derrota ou perde muito. Duvidoso = uma perda clara. Os números no tabuleiro valem saltar ali (≈1,0 = um salto de diferença), a seta é o melhor lance e a linha pontilhada o lance jogado.',
  'cr.forced': 'Era o único lance possível.', 'cr.open': 'Uma retirada de abertura. <b>{b}</b> era melhor.', 'cr.openOk': 'Uma retirada de abertura: boa escolha.',
